/** v1.0 Production control center. Face Follow remains strict opt-in. */
@UnstableApi
public class MainActivityV100 extends MainActivityV090 {
    private static final String TAB="v100_production_tab";
    private final Handler ui=new Handler(Looper.getMainLooper());
    private final ExecutorService worker=Executors.newSingleThreadExecutor();
    private boolean dead;private long createAt;
    private final Runnable loop=new Runnable(){public void run(){if(dead)return;try{fixVersion(getWindow().getDecorView());injectTab(getWindow().getDecorView());}catch(Throwable ignored){}ui.postDelayed(this,650);}};

    @Override public void onCreate(Bundle b){createAt=SystemClock.elapsedRealtime();super.onCreate(b);defaults();V100RecoveryWorker.schedule(this);ui.post(loop);ui.postDelayed(()->V100PerformanceKit.markLaunch(this,SystemClock.elapsedRealtime()-createAt),1200);if(!p().getBoolean("backend_benchmark_done_v100",false))worker.execute(()->{String x=V100PerformanceKit.tuneFaceBackend(this);runOnUiThread(()->Toast.makeText(this,"AI backend: "+x,Toast.LENGTH_LONG).show());});}
    @Override protected void onDestroy(){dead=true;ui.removeCallbacksAndMessages(null);worker.shutdownNow();super.onDestroy();}

    private SharedPreferences p(){return getSharedPreferences("actor_sticker",MODE_PRIVATE);}private int dp(int x){return Math.round(x*getResources().getDisplayMetrics().density);}
    private void defaults(){if(!p().getBoolean("v100_defaults_migrated",false))p().edit().putBoolean("v100_defaults_migrated",true).putBoolean("v090_face_follow_enabled",false).putBoolean("smart_tracking",false).putBoolean("dense_tracking_v060",false).putBoolean("dynamic_zoom_v050",false).putBoolean("cinematic_follow_v090",false).putString("tracking_motion_v061","Fixed actor average").putBoolean("unknown_person_v100",true).putBoolean("actor_lock2_v100",true).putBoolean("optical_flow_v100",true).putBoolean("body_reid_v100",true).putBoolean("persistent_jobs_v100",true).putString("identity_accuracy_v100","Balanced").putInt("flow_step_ms_v100",180).apply();}

    private void fixVersion(View v){if(v==null)return;if(v instanceof TextView){TextView t=(TextView)v;String s=String.valueOf(t.getText());if(s.contains("v0.9.0"))t.setText(s.replace("v0.9.0","v1.0.0"));else if(s.contains("v0.9")&&!s.contains("v1.0"))t.setText(s.replace("v0.9","v1.0"));}if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++)fixVersion(g.getChildAt(i));}}
    private void injectTab(View v){if(!(v instanceof ViewGroup))return;ViewGroup g=(ViewGroup)v;if(g instanceof LinearLayout&&g.getParent() instanceof HorizontalScrollView){boolean base=false;for(int i=0;i<g.getChildCount();i++)if(g.getChildAt(i) instanceof Button){String s=((Button)g.getChildAt(i)).getText().toString().toLowerCase(Locale.ROOT);if(s.contains("videos")||s.contains("ویدیو")||s.contains("video")){base=true;break;}}if(base){for(int i=0;i<g.getChildCount();i++)if(TAB.equals(g.getChildAt(i).getTag()))return;Button b=button(tr("Production"));b.setTag(TAB);b.setOnClickListener(x->showProduction());g.addView(b);return;}}for(int i=0;i<g.getChildCount();i++)injectTab(g.getChildAt(i));}

    private void showProduction(){LinearLayout c=content();if(c==null)return;c.removeAllViews();c.addView(title("Actor Sticker Cutter • v1.0 Production"));c.addView(note(tr("Face Follow is OFF by default. Nothing moves toward the selected face unless you enable it yourself.")));
        LinearLayout motion=card(tr("Camera & Tracking"));Switch follow=switcher(tr("Enable Face Follow"),p().getBoolean("v090_face_follow_enabled",false));motion.addView(follow);TextView fs=note(follow.isChecked()?tr("ON • optical/cinematic tracking can run"):tr("OFF • Fixed actor average • zero automatic pan/zoom"));motion.addView(fs);follow.setOnCheckedChangeListener((b,on)->{setFollow(on);showProduction();});Switch flow=switcher(tr("Lucas-Kanade optical-flow refinement"),p().getBoolean("optical_flow_v100",true));flow.setEnabled(follow.isChecked());flow.setOnCheckedChangeListener((b,on)->p().edit().putBoolean("optical_flow_v100",on).apply());motion.addView(flow);Switch body=switcher(tr("Body appearance recovery when face is temporarily lost"),p().getBoolean("body_reid_v100",true));body.setEnabled(follow.isChecked());body.setOnCheckedChangeListener((b,on)->p().edit().putBoolean("body_reid_v100",on).apply());motion.addView(body);Switch lock=switcher(tr("Actor Lock 2.0 • require consistent frames before a large identity jump"),p().getBoolean("actor_lock2_v100",true));lock.setOnCheckedChangeListener((b,on)->p().edit().putBoolean("actor_lock2_v100",on).apply());motion.addView(lock);c.addView(motion);

        LinearLayout identity=card(tr("Face Recognition v3"));Spinner profile=spinner(new String[]{"Fast","Balanced","Maximum Accuracy"},p().getString("identity_accuracy_v100","Balanced"));identity.addView(note(tr("Accuracy / speed profile")));identity.addView(profile);profile.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onItemSelected(AdapterView<?>a,View v,int pos,long id){String x=(String)a.getItemAtPosition(pos);p().edit().putString("identity_accuracy_v100",x).putString("speed_mode_v070",pos==0?"Quick":pos==2?"Ultra Accurate":"Balanced").apply();}public void onNothingSelected(AdapterView<?>a){}});Switch unknown=switcher(tr("Unknown / Needs Review instead of forced actor match"),p().getBoolean("unknown_person_v100",true));unknown.setOnCheckedChangeListener((b,on)->p().edit().putBoolean("unknown_person_v100",on).apply());identity.addView(unknown);
        ActorScanStore.ScanState state=state();int actor=selected();ActorScanStore.Cluster ac=state==null?null:state.byId(actor);if(state!=null&&ac!=null){identity.addView(note(V100IdentityEngine.summary(this,state.projectKey,actor)));Button refs=button(tr("Build multi-angle identity memory"));refs.setOnClickListener(v->worker.execute(()->{int n=V100IdentityEngine.buildFromActor(this,state,ac);runOnUiThread(()->Toast.makeText(this,"Identity memory: "+n+" reference(s)",Toast.LENGTH_LONG).show());}));identity.addView(refs);Button neg=button(tr("Teach nearest lookalike as hard negative"));neg.setOnClickListener(v->worker.execute(()->{String x=V100IdentityEngine.teachNearestHardNegative(this,state,actor);runOnUiThread(()->Toast.makeText(this,x,Toast.LENGTH_LONG).show());}));identity.addView(neg);}else identity.addView(note(tr("Select an actor to build identity memory and hard negatives.")));c.addView(identity);

        LinearLayout keys=card(tr("Keyframe Tracking Editor"));keys.addView(note(tr("Five manual camera keyframes. They only affect output when manual path / Face Follow is enabled.")));KeyEditor ed=new KeyEditor(this,p().getString("tracking_path_v090","0:0.5:0.42;0.25:0.5:0.42;0.5:0.5:0.42;0.75:0.5:0.42;1:0.5:0.42"));keys.addView(ed);Button save=button(tr("Save 5-point path"));save.setOnClickListener(v->{p().edit().putString("tracking_path_v090",ed.spec()).putBoolean("manual_path_v090",true).apply();Toast.makeText(this,tr("Manual path saved"),Toast.LENGTH_SHORT).show();});keys.addView(save);Button fixed=button(tr("Reset path to fixed center"));fixed.setOnClickListener(v->{p().edit().putString("tracking_path_v090","0:0.5:0.42;0.25:0.5:0.42;0.5:0.5:0.42;0.75:0.5:0.42;1:0.5:0.42").putBoolean("manual_path_v090",false).apply();showProduction();});keys.addView(fixed);c.addView(keys);

        LinearLayout preview=card(tr("WYSIWYG Preview"));Button pv=button(tr("Render 4-second preview with the exact export crop pipeline"));pv.setOnClickListener(v->invoke("renderPreview"));preview.addView(pv);preview.addView(note(tr("Preview is rendered through the same TrackingPanEffect + Crop + Media3 Transformer path used by export.")));c.addView(preview);

        LinearLayout hw=card(tr("Hardware Auto Tuning"));TextView backend=note("AI: "+V100PerformanceKit.perfSummary(this));hw.addView(backend);Button tune=button(tr("Benchmark CPU vs NNAPI accelerator"));tune.setOnClickListener(v->{tune.setEnabled(false);worker.execute(()->{String x=V100PerformanceKit.tuneFaceBackend(this);runOnUiThread(()->{new AlertDialog.Builder(this).setTitle(tr("AI Backend Result")).setMessage(x+"\n\nNNAPI lets Android choose an available NPU/GPU/DSP accelerator when supported.").setPositiveButton("OK",null).show();tune.setEnabled(true);});});});hw.addView(tune);Button codec=button(tr("Benchmark AVC / HEVC hardware encoder"));codec.setOnClickListener(v->{codec.setEnabled(false);worker.execute(()->{String x=V100PerformanceKit.analyzeCodecs(this);runOnUiThread(()->{new AlertDialog.Builder(this).setTitle(tr("Codec Analyzer")).setMessage(x).setPositiveButton("OK",null).show();codec.setEnabled(true);});});});hw.addView(codec);c.addView(hw);

        LinearLayout reliability=card(tr("Persistent Jobs & Recovery"));Switch persist=switcher(tr("Persistent WorkManager recovery"),p().getBoolean("persistent_jobs_v100",true));persist.setOnCheckedChangeListener((b,on)->{p().edit().putBoolean("persistent_jobs_v100",on).apply();if(on)V100RecoveryWorker.schedule(this);});reliability.addView(persist);reliability.addView(note(tr("Foreground scan/export keeps running normally. WorkManager additionally repairs stalled queue state after process death or reboot and retries service recovery when Android allows it.")));Button repair=button(tr("One-Tap Repair Project"));repair.setEnabled(state!=null);repair.setOnClickListener(v->worker.execute(()->{String x=V100ProjectRepair.repair(this,state==null?"":state.projectKey);runOnUiThread(()->new AlertDialog.Builder(this).setTitle(tr("Repair Result")).setMessage(x).setPositiveButton("OK",null).show());}));reliability.addView(repair);c.addView(reliability);

        LinearLayout quality=card(tr("Accuracy & Regression Report"));Button ar=button(tr("Actor Accuracy Report"));ar.setEnabled(state!=null&&ac!=null);ar.setOnClickListener(v->new AlertDialog.Builder(this).setTitle(tr("Accuracy Report")).setMessage(V100PerformanceKit.accuracyReport(this,state,actor)).setPositiveButton("OK",null).show());quality.addView(ar);Button reg=button(tr("Run Production Regression Test"));reg.setOnClickListener(v->{reg.setEnabled(false);worker.execute(()->{String x=V100PerformanceKit.regression(this,state);runOnUiThread(()->{new AlertDialog.Builder(this).setTitle(tr("Regression Test")).setMessage(x).setPositiveButton("OK",null).show();reg.setEnabled(true);});});});quality.addView(reg);quality.addView(note(tr("Report measures confidence, low-confidence frames, possible identity switches and tracking jitter. Precision is an estimate from identity confidence, not manually labeled ground truth.")));c.addView(quality);
    }

    private void setFollow(boolean on){SharedPreferences.Editor e=p().edit().putBoolean("v090_face_follow_enabled",on).putBoolean("smart_tracking",on).putBoolean("dense_tracking_v060",on);if(on)e.putString("tracking_motion_v061","Slow");else e.putBoolean("dynamic_zoom_v050",false).putBoolean("cinematic_follow_v090",false).putBoolean("manual_path_v090",false).putString("tracking_motion_v061","Fixed actor average");e.apply();}
    private LinearLayout content(){try{Field f=MainActivity.class.getDeclaredField("content");f.setAccessible(true);return(LinearLayout)f.get(this);}catch(Throwable e){return null;}}
    private ActorScanStore.ScanState state(){try{Field f=MainActivity.class.getDeclaredField("scanState");f.setAccessible(true);Object x=f.get(this);if(x instanceof ActorScanStore.ScanState)return(ActorScanStore.ScanState)x;}catch(Throwable ignored){}try{Method m=findMethod("projectKey");if(m!=null){String k=String.valueOf(m.invoke(this));return new ActorScanStore(this).load(k);}}catch(Throwable ignored){}return null;}
    private int selected(){try{Field f=MainActivity.class.getDeclaredField("selectedClusterId");f.setAccessible(true);return f.getInt(this);}catch(Throwable e){return-1;}}
    private Method findMethod(String name,Class<?>...types){Class<?>x=getClass();while(x!=null){try{Method m=x.getDeclaredMethod(name,types);m.setAccessible(true);return m;}catch(Throwable e){x=x.getSuperclass();}}return null;}
    private void invoke(String name){try{Method m=findMethod(name);if(m!=null)m.invoke(this);}catch(Throwable e){Toast.makeText(this,name+" unavailable",Toast.LENGTH_SHORT).show();}}

    private LinearLayout card(String s){LinearLayout x=new LinearLayout(this);x.setOrientation(LinearLayout.VERTICAL);x.setPadding(dp(12),dp(10),dp(12),dp(10));x.addView(label(s,17,true));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,dp(6),0,dp(6));x.setLayoutParams(lp);return x;}private TextView title(String s){return label(s,22,true);}private TextView note(String s){TextView t=label(s,12,false);t.setAlpha(.75f);return t;}private TextView label(String s,int sp,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(sp);if(bold)t.setTypeface(null,1);t.setPadding(dp(5),dp(5),dp(5),dp(5));return t;}private Button button(String s){Button b=new Button(this);b.setText(s);b.setAllCaps(false);return b;}private Switch switcher(String s,boolean on){Switch w=new Switch(this);w.setText(s);w.setChecked(on);return w;}private Spinner spinner(String[]a,String sel){Spinner s=new Spinner(this);ArrayAdapter<String>x=new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,a);s.setAdapter(x);for(int i=0;i<a.length;i++)if(a[i].equals(sel)){s.setSelection(i);break;}return s;}

    private String tr(String en){String l=p().getString("language_v060","en");if("en".equals(l))return en;Map<String,String[]>d=dict();String[]x=d.get(en);if(x==null)return en;return x["fa".equals(l)?0:"tr".equals(l)?1:2];}
    private Map<String,String[]>dict(){LinkedHashMap<String,String[]>m=new LinkedHashMap<>();m.put("Production",new String[]{"نسخه حرفه‌ای","Üretim","Продакшн"});m.put("Face Follow is OFF by default. Nothing moves toward the selected face unless you enable it yourself.",new String[]{"دنبال‌کردن چهره به‌صورت پیش‌فرض خاموش است و تا خودت روشنش نکنی قاب سمت صورت حرکت نمی‌کند.","Yüz takibi varsayılan olarak kapalıdır; siz açmadıkça kadraj yüze doğru hareket etmez.","Слежение за лицом по умолчанию выключено; кадр не двигается к лицу, пока вы сами его не включите."});m.put("Camera & Tracking",new String[]{"دوربین و Tracking","Kamera ve Takip","Камера и трекинг"});m.put("Enable Face Follow",new String[]{"فعال‌کردن دنبال‌کردن چهره","Yüz Takibini Aç","Включить слежение за лицом"});m.put("OFF • Fixed actor average • zero automatic pan/zoom",new String[]{"خاموش • قاب ثابت روی میانگین بازیگر • بدون حرکت و زوم خودکار","Kapalı • Oyuncu ortalamasında sabit • otomatik pan/zoom yok","Выкл. • фиксированный средний кадр актёра • без автопанорамы/зума"});m.put("ON • optical/cinematic tracking can run",new String[]{"روشن • Tracking اپتیکال/سینمایی می‌تواند اجرا شود","Açık • optik/sinematik takip çalışabilir","Вкл. • доступен оптический/кинематографический трекинг"});m.put("Lucas-Kanade optical-flow refinement",new String[]{"اصلاح مسیر با Optical Flow لوکاس–کاناده","Lucas-Kanade optik akış iyileştirmesi","Уточнение оптическим потоком Lucas–Kanade"});m.put("Body appearance recovery when face is temporarily lost",new String[]{"بازیابی با ظاهر بدن وقتی چهره موقتاً گم می‌شود","Yüz kısa süre kaybolduğunda gövde görünümüyle kurtarma","Восстановление по внешнему виду тела при временной потере лица"});m.put("Face Recognition v3",new String[]{"تشخیص چهره v3","Yüz Tanıma v3","Распознавание лиц v3"});m.put("Accuracy / speed profile",new String[]{"پروفایل دقت / سرعت","Doğruluk / hız profili","Профиль точность / скорость"});m.put("Unknown / Needs Review instead of forced actor match",new String[]{"Unknown / نیاز به بررسی به‌جای نسبت‌دادن اجباری بازیگر","Zorunlu eşleşme yerine Unknown / İnceleme Gerekli","Unknown / Требует проверки вместо принудительного совпадения"});m.put("Build multi-angle identity memory",new String[]{"ساخت حافظه هویتی چندزاویه‌ای","Çok açılı kimlik belleği oluştur","Создать многоракурсную память личности"});m.put("Teach nearest lookalike as hard negative",new String[]{"یادگیری نزدیک‌ترین فرد مشابه به‌عنوان Hard Negative","En yakın benzeri hard negative olarak öğret","Обучить ближайшего двойника как hard negative"});m.put("Keyframe Tracking Editor",new String[]{"ویرایشگر Keyframe مسیر Crop","Keyframe Takip Düzenleyici","Редактор ключевых кадров трекинга"});m.put("Save 5-point path",new String[]{"ذخیره مسیر ۵ نقطه‌ای","5 noktalı yolu kaydet","Сохранить путь из 5 точек"});m.put("Reset path to fixed center",new String[]{"برگرداندن مسیر به قاب ثابت","Yolu sabit merkeze sıfırla","Сбросить путь к фиксированному центру"});m.put("WYSIWYG Preview",new String[]{"پیش‌نمایش دقیق خروجی","WYSIWYG Önizleme","WYSIWYG предпросмотр"});m.put("Hardware Auto Tuning",new String[]{"تنظیم خودکار سخت‌افزار","Otomatik Donanım Ayarı","Автонастройка оборудования"});m.put("Benchmark CPU vs NNAPI accelerator",new String[]{"Benchmark پردازنده در برابر NNAPI","CPU ve NNAPI hız testi","Тест CPU против NNAPI"});m.put("Benchmark AVC / HEVC hardware encoder",new String[]{"Benchmark انکودر سخت‌افزاری AVC / HEVC","AVC / HEVC donanım kodlayıcı testi","Тест аппаратного AVC / HEVC"});m.put("Persistent Jobs & Recovery",new String[]{"Job پایدار و بازیابی","Kalıcı İşler ve Kurtarma","Постоянные задания и восстановление"});m.put("Persistent WorkManager recovery",new String[]{"بازیابی پایدار با WorkManager","WorkManager kalıcı kurtarma","Постоянное восстановление WorkManager"});m.put("One-Tap Repair Project",new String[]{"تعمیر پروژه با یک لمس","Tek Dokunuşla Proje Onarımı","Восстановить проект одним нажатием"});m.put("Accuracy & Regression Report",new String[]{"گزارش دقت و Regression","Doğruluk ve Regresyon Raporu","Отчёт точности и регрессии"});m.put("Actor Accuracy Report",new String[]{"گزارش دقت بازیگر","Oyuncu Doğruluk Raporu","Отчёт точности актёра"});m.put("Run Production Regression Test",new String[]{"اجرای تست Regression نسخه Production","Production Regresyon Testini Çalıştır","Запустить регрессионный тест Production"});return m;}

    private static final class KeyEditor extends LinearLayout{final SeekBar[]xs=new SeekBar[5],ys=new SeekBar[5];KeyEditor(Context c,String spec){super(c);setOrientation(VERTICAL);float[][]v=parse(spec);for(int i=0;i<5;i++){TextView h=new TextView(c);h.setText(String.format(Locale.US,"Key %d • %d%%",i+1,i*25));addView(h);LinearLayout row=new LinearLayout(c);row.setOrientation(HORIZONTAL);xs[i]=seek(c,Math.round(v[i][0]*100));ys[i]=seek(c,Math.round(v[i][1]*100));row.addView(text(c,"X"));row.addView(xs[i],new LayoutParams(0,-2,1));row.addView(text(c,"Y"));row.addView(ys[i],new LayoutParams(0,-2,1));addView(row);}}String spec(){StringBuilder b=new StringBuilder();for(int i=0;i<5;i++){if(i>0)b.append(';');b.append(String.format(Locale.US,"%.2f:%.2f:%.2f",i*.25f,xs[i].getProgress()/100f,ys[i].getProgress()/100f));}return b.toString();}private static SeekBar seek(Context c,int v){SeekBar s=new SeekBar(c);s.setMax(100);s.setProgress(Math.max(4,Math.min(96,v)));return s;}private static TextView text(Context c,String s){TextView t=new TextView(c);t.setText(s);t.setPadding(6,0,6,0);return t;}private static float[][]parse(String s){float[][]o={{.5f,.42f},{.5f,.42f},{.5f,.42f},{.5f,.42f},{.5f,.42f}};try{String[]p=s.split(";");for(int i=0;i<Math.min(5,p.length);i++){String[]q=p[i].split(":");if(q.length>=3){o[i][0]=Float.parseFloat(q[1]);o[i][1]=Float.parseFloat(q[2]);}}}catch(Throwable ignored){}return o;}}
}
